import{_ as t,c as n,o as a,a3 as o}from"./chunks/framework.Dokpd4od.js";const g=JSON.parse('{"title":"Accounting entries overview","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/accounting-entries/index.md","filePath":"master/finance/accounting-entries/index.md","lastUpdated":1793074831000}'),r={name:"master/finance/accounting-entries/index.md"};function s(i,e,l,c,u,d){return a(),n("div",null,e[0]||(e[0]=[o('<h1 id="accounting-entries-overview" tabindex="-1">Accounting entries overview <a class="header-anchor" href="#accounting-entries-overview" aria-label="Permalink to &quot;Accounting entries overview&quot;">​</a></h1><p>Every money event in Aureus leaves a trace in the books. That trace has two parts: a journal entry and its journal items. Invoices, bills, payments and manual adjustments all create them.</p><blockquote><p><strong>In simple words:</strong> A journal entry is one page in the ledger book. The journal items are the lines on that page.</p></blockquote><p>These screens exist in the Accounting app only. Open them from <code>Accounting → Journal Entries</code> and <code>Accounting → Journal Items</code>.</p><h2 id="journal-entries-and-journal-items" tabindex="-1">Journal entries and journal items <a class="header-anchor" href="#journal-entries-and-journal-items" aria-label="Permalink to &quot;Journal entries and journal items&quot;">​</a></h2><ul><li><strong>Journal entry:</strong> One record with a number, a date, a journal and a status. Example: <code>INV/2026/1</code>.</li><li><strong>Journal item:</strong> One line of an entry. It names an account, a partner, a label, and an amount in <strong>Debit</strong> or <strong>Credit</strong>.</li></ul><div class="info custom-block"><p class="custom-block-title">Debit and credit</p><p><strong>Debit</strong> and <strong>Credit</strong> are the two sides of an entry. Money that comes in or an asset that grows is a debit. Money that goes out or a debt that grows is a credit. The two sides always match.</p></div><p>Every entry holds two or more items. The total debit should equal the total credit. That is the rule of double entry.</p><h2 id="how-documents-create-entries" tabindex="-1">How documents create entries <a class="header-anchor" href="#how-documents-create-entries" aria-label="Permalink to &quot;How documents create entries&quot;">​</a></h2><p>You do not have to type entries for normal work. Aureus builds them for you.</p><ol><li><strong>Customer invoice:</strong> When you confirm <strong>INV/2026/1</strong> for $1,207.50, Aureus debits <strong>Account Receivable</strong> with $1,207.50. It credits <strong>Product Sales</strong> with $1,050.00 and <strong>Tax Received</strong> with $157.50.</li><li><strong>Vendor bill:</strong> A bill debits expense and tax accounts. It credits <strong>Account Payable</strong>.</li><li><strong>Payment:</strong> When a customer pays, Aureus debits <strong>Outstanding Receipts</strong> and credits <strong>Account Receivable</strong>. A vendor payment does the reverse with <strong>Outstanding Payments</strong>.</li><li><strong>Matching:</strong> The payment line and the invoice line on <strong>Account Receivable</strong> are matched. The invoice is then settled.</li></ol><h2 id="when-to-type-an-entry-yourself" tabindex="-1">When to type an entry yourself <a class="header-anchor" href="#when-to-type-an-entry-yourself" aria-label="Permalink to &quot;When to type an entry yourself&quot;">​</a></h2><p>Create a manual entry for events that no document covers, for example a correction or a year start balance. Use the <strong>Miscellaneous</strong> journal for it. See <a href="./journal-entries.html">Journal entries</a>.</p><h2 id="entry-status" tabindex="-1">Entry status <a class="header-anchor" href="#entry-status" aria-label="Permalink to &quot;Entry status&quot;">​</a></h2><ul><li><strong>Draft:</strong> You can still change it. It does not count in reports.</li><li><strong>Posted:</strong> It is final. Reports count it.</li><li><strong>Cancelled:</strong> It was cancelled and does not count.</li></ul><p>Reports such as the balance sheet read posted entries only. See <a href="./../reporting/">Reporting</a>.</p><h2 id="in-this-section" tabindex="-1">In this section <a class="header-anchor" href="#in-this-section" aria-label="Permalink to &quot;In this section&quot;">​</a></h2><ul><li><a href="./journal-entries.html">Journal entries</a>: list, create and post entries.</li><li><a href="./journal-items.html">Journal items</a>: browse every line, filter and group them.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../get-started/chart-of-accounts.html">Chart of accounts</a></li><li><a href="./../get-started/journals.html">Journals</a></li><li><a href="./../payments/register-payment.html">Register a payment</a></li></ul>',20)]))}const m=t(r,[["render",s]]);export{g as __pageData,m as default};
